// Curated lesson notes adapted from the Downloads workspace's astronomy modules.
// Each lesson carries: keyIdea, body, points, dive (deep dive), terms (glossary),
// activity (hands-on), quick (30-second check) and fact — plus a module-level quiz.
export const modules = [
  { title: 'Foundations of Astronomy', subtitle: 'How we study the sky', image: 'visual-cosmicweb.png', accent: 'amber', intro: 'Astronomy is the scientific study of everything beyond Earth. It uses observation, evidence, mathematics, telescopes and spacecraft to explain how the cosmos works.', topics: [
    { title: 'Astronomy is a science', body: 'Astronomy tests explanations against observations. Astrology is a belief-based practice that links celestial positions with human lives; its predictions are not scientifically established.', points: ['Observe a pattern in the sky.', 'Ask a focused question and propose a testable explanation.', 'Collect evidence, analyse it, and revise the explanation when needed.'], keyIdea: 'Astronomy earns the name science by testing explanations against observations — belief alone never settles a question.', dive: 'A scientific model must make predictions that could fail. When Einstein’s general relativity predicted that starlight should bend near the Sun, the 1919 eclipse expedition went out and measured exactly that bend. Astrology, by contrast, has failed controlled tests repeatedly — its forecasts perform no better than chance.', terms: [['hypothesis', 'A proposed explanation, stated clearly enough that observations could prove it wrong.'], ['prediction', 'A specific result a model says you should see if it is correct — the bridge between an idea and a test.'], ['evidence', 'Measurements and observations gathered from the world — the only court that science recognises.']], activity: 'Tonight, note where the Moon sits at the same hour on three evenings. Its shift against the stars is a real measurement — the first step of every science.', quick: { q: 'What turns a guess into scientific knowledge?', options: ['Testing its predictions against evidence', 'Repeating it with confidence', 'Publishing it in a popular book'], answer: 0, explain: 'A claim becomes science when observations can support or refute it. Astronomy passes that test nightly; astrology never has.' }, fact: 'A planet shifting position night after night is something astronomers can measure and explain.' },
    { title: 'A ladder of cosmic distances', body: 'Kilometres work for nearby worlds, but astronomy needs larger distance units for stars and galaxies.', points: ['1 AU is the average Earth–Sun distance: about 149.6 million km.', 'A light-year is a distance: how far light travels in one year, about 9.46 trillion km.', 'A parsec is about 3.26 light-years.'], keyIdea: 'Distance in astronomy is measured rung by rung: AU for planets, light-years and parsecs for stars.', dive: 'The first rung beyond the Solar System is parallax: as Earth orbits, nearby stars shift slightly against distant ones. The nearest star system, Proxima Centauri, still lies about 4.2 light-years away — roughly 268,000 AU — so the ladder has to keep climbing.', terms: [['astronomical unit (AU)', 'The average Earth–Sun distance, about 149.6 million km — the ruler for our own neighbourhood.'], ['light-year', 'How far light travels in one year, about 9.46 trillion km. A distance, never a time.'], ['parallax', 'The apparent shift of a nearby star against the background as Earth moves around the Sun.']], activity: 'Hold one finger at arm’s length and close each eye in turn — the finger jumps. Earth’s orbit plays the same trick on nearby stars.', quick: { q: 'Which of these distances is the largest?', options: ['1 astronomical unit', 'The Moon’s orbit', '1 light-year'], answer: 2, explain: 'One light-year is about 63,000 AU, while the Moon’s orbit is a mere 2.6 light-seconds across.' }, fact: 'Sunlight takes about 8 minutes 20 seconds to cross 1 AU.' },
    { title: 'The sky in motion', body: 'Earth’s rotation makes the entire sky appear to turn once each day around a point near Polaris. The constellations are patterns people drew between stars that sit at very different distances — the figures are chance alignments, not physical groups.', points: ['Stars rise in the east, cross the sky and set in the west as Earth spins.', 'Polaris sits almost exactly on the north celestial pole, so it barely moves all night.', 'From mid-northern latitudes, circumpolar constellations such as Ursa Major never set below the horizon.'], keyIdea: 'The daily wheeling of the sky is Earth’s rotation; constellations are chance alignments, not real groups.', dive: 'How much of the sky never sets depends on your latitude. At the North Pole, Polaris stands overhead and half the sky is circumpolar; at the equator it sits on the horizon, and every star gets roughly twelve hours above the horizon each night.', terms: [['celestial pole', 'The point in the sky around which everything appears to turn — Earth’s rotation axis extended out to the stars.'], ['circumpolar', 'A constellation that never sets for your latitude because it circles close to the pole.'], ['light pollution', 'Artificial sky glow that hides faint stars; cities reveal dozens of stars, dark rural sites reveal thousands.']], activity: 'From a window facing north, find Polaris and sketch the Big Dipper’s shape tonight, then again three hours later — the dipper will have wheeled around the pole.', quick: { q: 'Why does Polaris barely move during the night?', options: ['It is stationary in space', 'It lies almost exactly along Earth’s rotation axis', 'It is too far away to drift'], answer: 1, explain: 'Polaris sits within about one degree of the north celestial pole, so Earth’s spin turns the whole sky around it.' }, fact: 'Polaris is not the brightest star in the night sky — that title belongs to Sirius.' },
    { title: 'Brightness, colour and temperature', body: 'Astronomers rank brightness with the magnitude scale: smaller numbers mean brighter objects, and the numbers can even turn negative. A star’s colour is a thermometer — blue-white stars burn hottest, while orange-red ones are the coolest.', points: ['The Sun shines at magnitude −26.7; Sirius, the brightest night-time star, sits at −1.5.', 'Under a truly dark sky, most people can just make out stars near magnitude 6.', 'Rigel glows blue-white at around 12,000 °C; Betelgeuse is a cool red supergiant near 3,500 °C.'], keyIdea: 'Magnitude ranks how bright something looks; colour betrays surface temperature — blue is hot, red is cool.', dive: 'The magnitude scale is logarithmic: five magnitudes equal a 100-fold jump in brightness. That is why the Sun at −26.7 outshines Sirius at −1.5 by roughly ten billion times in our sky — even though Sirius itself is intrinsically far more luminous.', terms: [['apparent magnitude', 'How bright an object looks from Earth; smaller (or negative) numbers mean brighter.'], ['spectral class', 'The letter O–M order sorting stars from hottest (blue) to coolest (red); the Sun is a G2 star.'], ['kelvin', 'The temperature scale astronomers use; 0 K is absolute zero, and the Sun’s surface runs near 5,800 K.']], activity: 'On a clear night compare Orion’s shoulders: Betelgeuse glows orange near 3,500 °C while Rigel burns blue-white near 12,000 °C — a thermometer you can see.', quick: { q: 'Which of these stars has the hottest surface?', options: ['Betelgeuse, orange-red', 'Rigel, blue-white', 'The Sun, yellow'], answer: 1, explain: 'Colour is temperature: Rigel’s blue-white glow marks a much hotter surface than Betelgeuse’s red-orange or the Sun’s yellow.' }, fact: 'Compare Orion’s shoulders some clear night: Betelgeuse looks orange while Rigel looks blue.' },
    { title: 'Tools of the observer', body: 'From naked-eye star charts to binoculars, backyard telescopes and orbiting observatories, every tool collects more light or sharper detail. Refractors bend light through lenses, reflectors bounce it off mirrors, and space telescopes rise above the blur and glare of the atmosphere.', points: ['Aperture wins: a bigger mirror or lens gathers more light, revealing fainter objects.', 'Galileo’s small telescope, at roughly 30× magnification, was enough to reveal Jupiter’s moons in 1610.', 'Radio, infrared and X-ray observatories open parts of the spectrum our eyes can never see.'], keyIdea: 'Aperture gathers light, resolution sharpens it, and the wavelength you choose decides what a telescope can show.', dive: 'Aperture can also be faked by teamwork: link several radio dishes into an interferometer and they behave like one instrument as wide as the gap between them. That is the trick behind the first image of a black hole, made with dishes spanning the whole planet.', terms: [['aperture', 'The diameter of a telescope’s main lens or mirror; bigger means more collected light.'], ['refractor', 'A telescope that bends light through lenses, like Galileo’s 1610 instrument.'], ['reflector', 'A telescope that gathers light with a curved mirror — the design of nearly all modern instruments.']], activity: 'Steady a pair of binoculars on a railing and look at Jupiter: its four bright moons appear exactly as they did to Galileo in 1610.', quick: { q: 'To reveal fainter objects, a telescope mainly needs…', options: ['Higher magnification', 'A larger aperture', 'A longer tube'], answer: 1, explain: 'Light-gathering grows with the area of the aperture, so diameter — not magnification — sets how faint you can see.' }, fact: 'A city’s light pollution can hide all but a few dozen stars; a dark rural site reveals thousands.' }
  ], quiz: [
    { q: 'Which practice tests its explanations against observations?', options: ['Astronomy', 'Astrology'], answer: 0, explain: 'Astronomy is a science: ideas are tested against evidence. Astrology is belief-based, and its predictions are not scientifically established.' },
    { q: 'A light-year measures…', options: ['How bright a star really is', 'How long a star lives', 'How far light travels in one year'], answer: 2, explain: 'A light-year is a distance: about 9.46 trillion kilometres.' },
    { q: 'Why do stars appear to wheel around Polaris during the night?', options: ['The stars orbit Polaris', 'Earth rotates on its axis', 'Polaris pulls on nearby stars'], answer: 1, explain: 'Earth’s rotation makes the whole sky appear to turn once a day around the pole.' }
  ] },
  { title: 'History of Astronomy', subtitle: 'Many cultures, many discoveries', image: 'visual-starmap.png', accent: 'gold', intro: 'People in many parts of the world tracked the sky to understand seasons, make calendars and navigate. Astronomy changed as observations and instruments improved.', topics: [
    { title: 'Before telescopes', body: 'Babylonian astronomers recorded celestial cycles and developed ways to predict events. Greek, Indian, Chinese and Islamic scholars added models, mathematics, observations and instruments.', points: ['Aryabhata described Earth rotating on its axis.', 'Chinese astronomers kept records of comets, eclipses and supernovae.', 'Al-Battani and Al-Sufi made careful measurements and star records.'], keyIdea: 'Centuries before telescopes, patient sky records across cultures turned astronomy into a predictive science.', dive: 'Chinese court astronomers recorded the “guest star” of 1054; nearly a thousand years later its remnant — the Crab Nebula — was matched to that record. Old observations never stop being useful.', terms: [['Saros cycle', 'An 18-year, 11-day rhythm in which eclipses repeat, known to Babylonian skywatchers.'], ['ephemeris', 'A table giving the calculated positions of a celestial object at regular intervals.'], ['guest star', 'The Chinese term for a sudden new light in the sky — what we now recognise as a supernova or comet.']], activity: 'Log the Moon’s position against bright stars for a week. Babylonian scribes built eclipse prediction from exactly such patient records.', quick: { q: 'Which ancient records helped identify the Crab Nebula as a supernova remnant?', options: ['Babylonian horoscopes', 'Chinese records of 1054', 'Mayan calendars'], answer: 1, explain: 'The “guest star” of 1054 was recorded by Chinese astronomers, letting modern astronomers match it to the Crab Nebula.' } },
    { title: 'A changing model of the sky', body: 'Copernicus proposed a Sun-centred model. Galileo’s telescope revealed Jupiter’s large moons and the phases of Venus. Kepler described elliptical planetary orbits; Newton explained them with gravity and motion.', points: ['1609 — Galileo turns a telescope toward the sky.', '1687 — Newton publishes the law of universal gravitation.', '1924 — Hubble shows that Andromeda lies beyond the Milky Way.'], keyIdea: 'Every sharper observation — phases, moons, ellipses, gravity — pushed Earth out of the centre of the model.', dive: 'Galileo’s Venus was the decisive blow: his telescope showed Venus a full set of phases, which is only possible if it circles the Sun. A purely Earth-centred orbit can never show Venus “full”.', terms: [['geocentric', 'The model placing a motionless Earth at the centre of everything.'], ['heliocentric', 'The Sun-centred model argued by Copernicus and confirmed by Galileo’s evidence.'], ['phase', 'The lit portion of a world we can see, like the Moon’s — the clue Galileo spotted on Venus.']], activity: 'With binoculars, watch Jupiter’s four bright moons over several nights — their nightly dance is the very evidence Galileo sketched in 1610.', quick: { q: 'Kepler’s key correction to the old circular orbits was…', options: ['Planets move on ellipses', 'Planets move on faster circles', 'Planets orbit Earth slowly'], answer: 0, explain: 'From Tycho’s data Kepler found that planetary orbits are ellipses with the Sun at one focus.' } },
    { title: 'Kepler, Newton and the clockwork sky', body: 'Tycho Brahe spent decades measuring planetary positions with naked-eye instruments of unmatched precision. Johannes Kepler mined that data and discovered the planets move in ellipses; Isaac Newton then explained why with a single law of gravitation covering both falling apples and orbiting moons.', points: ['Kepler’s laws: orbits are ellipses; planets sweep equal areas in equal times; the orbital period grows with the 3/2 power of the orbit’s size.', 'Newton published the law of universal gravitation in the Principia, in 1687.', 'Edmond Halley used the new mechanics to predict a comet’s return — it arrived in 1758, just as calculated.'], keyIdea: 'Tycho’s measurements, Kepler’s laws and Newton’s gravity made the sky a single clockwork system.', dive: 'The system’s power was proven by prediction: Halley used Newton’s mechanics to recognise that the comets of 1531, 1607 and 1682 were one repeating visitor, and forecast its return for 1758. It arrived on schedule — sixteen years after his death.', terms: [['law of universal gravitation', 'Newton’s 1687 rule: every mass attracts every other with a force that weakens with the square of distance.'], ['orbital period', 'The time one orbit takes; Kepler showed it grows with the 3/2 power of the orbit’s size.'], ['comet', 'An icy small body that grows a glowing coma and tail when warmed near the Sun.']], activity: 'Drop a coin and watch it fall, then recall that the same law curves the Moon’s path — gravity writes both motions at once.', quick: { q: 'Halley used Newton’s mechanics to…', options: ['Weigh the Sun', 'Predict a comet’s 1758 return', 'Discover Neptune'], answer: 1, explain: 'Applying the new gravitation to comet records, Halley correctly forecast the return of “his” comet in 1758.' }, fact: 'Newton’s gravity let astronomers weigh planets by timing the orbits of their moons.' },
    { title: 'Great observatories, new worlds', body: 'Bigger telescopes kept redrawing the sky map. Uranus turned up in Herschel’s reflector in 1781; Neptune was computed on paper and found within a degree of the prediction in 1846. In 1838 Bessel measured the first stellar parallax, finally proving how far the stars really are.', points: ['1781 — William Herschel discovers Uranus with a telescope he built himself.', '1838 — Friedrich Bessel measures the parallax of 61 Cygni: about 11 light-years away.', '1924 — Edwin Hubble, using the 100-inch Hooker telescope, proves Andromeda is a galaxy of its own.'], keyIdea: 'Bigger telescopes plus patient mathematics found new planets and measured true stellar distances.', dive: 'Neptune was found with the point of a pen: Urbain Le Verrier computed where an unseen planet must sit to explain Uranus’s wanderings, and Johann Galle found it within one degree of the prediction on his first night of looking, in 1846.', terms: [['stellar parallax', 'The tiny annual shift of a nearby star used to measure its distance; Bessel first measured one in 1838.'], ['perturbation', 'A small deviation of an orbit caused by the pull of another body — the clue that revealed Neptune.'], ['reflecting telescope', 'A mirror-based telescope; Herschel’s 1781 discovery of Uranus came from one he ground himself.']], activity: 'Compare Galileo’s 1610 Moon sketches with the view through binoculars tonight — the craters along the terminator look exactly the same.', quick: { q: 'How was Neptune discovered in 1846?', options: ['By chance during a comet survey', 'Within 1° of a mathematical prediction', 'By naked eye, as the Babylonians had'], answer: 1, explain: 'Le Verrier predicted Neptune’s position from Uranus’s perturbations; Galle found it on the first night, within one degree.' }, fact: 'Newspapers hailed Neptune as a planet discovered “with the point of a pen”.' }
  ], quiz: [
    { q: 'Who described Earth rotating on its axis, centuries before Copernicus?', options: ['Aryabhata', 'Tycho Brahe', 'Edmond Halley'], answer: 0, explain: 'Aryabhata described Earth’s rotation in the 5th century.' },
    { q: 'What did Galileo see that made a Sun-centred sky more believable?', options: ['Rings around Uranus', 'Mountains on the Sun', 'Venus’s phases and moons circling Jupiter'], answer: 2, explain: 'Venus’s phases fit orbits around the Sun, and Jupiter’s moons showed that not everything circles Earth.' },
    { q: 'Whose decades of precise naked-eye measurements did Kepler use to find elliptical orbits?', options: ['Tycho Brahe', 'Galileo', 'Al-Sufi'], answer: 0, explain: 'Kepler mined Tycho Brahe’s planetary positions to discover his three laws.' }
  ] },
  { title: 'The Solar System', subtitle: 'The Sun and what it holds', image: 'visual-saturn.png', accent: 'cyan', intro: 'The Solar System formed about 4.6 billion years ago from a cloud of gas and dust. The Sun holds nearly all its mass; eight planets and many smaller bodies orbit under its gravity.', topics: [
    { title: 'Eight planets, two broad groups', body: 'The inner planets are rocky. Beyond the asteroid belt are the much larger gas and ice giants.', points: ['Mercury is the smallest; Venus is the hottest; Earth is the only world known to support life.', 'Mars is a cold, iron-rich world. Jupiter is the largest planet and has the Great Red Spot.', 'Saturn has a bright ring system; Uranus rotates on its side; Neptune has powerful winds.'], keyIdea: 'Composition follows heat: rocky worlds near the Sun, gas and ice giants beyond the frost line.', dive: 'Jupiter outweighs every other planet combined — more than twice over. Its Great Red Spot, a storm wider than Earth, has raged for centuries, though it has been visibly shrinking since the 1800s.', terms: [['terrestrial planet', 'A rocky Earth-like world: Mercury, Venus, Earth or Mars.'], ['gas giant', 'A planet dominated by hydrogen and helium, like Jupiter and Saturn.'], ['ice giant', 'Uranus and Neptune, built around water, ammonia and methane ices.']], activity: 'Find Saturn with even a small telescope and sketch its rings once a season — their tilt changes as the planet orbits.', quick: { q: 'Why are the four inner planets rocky?', options: ['They formed where heat stripped away ices and gas', 'They are the oldest planets', 'The Sun’s gravity crushed their gas'], answer: 0, explain: 'Near the young Sun only rock and metal survived the heat; ices stayed beyond the frost line, where giants grew.' } },
    { title: 'A cloud becomes a system', body: 'The Solar System began as a slowly rotating cloud of gas and dust. Gravity flattened it into a disk with the young Sun at its heart; grains collided and stuck, growing into planetesimals and then planets. Near the Sun only rock and metal endured the heat; beyond the frost line, ices let giant worlds grow.', points: ['The frost line lay roughly where Jupiter now orbits — inside it the rocky planets formed, outside it ice-rich cores captured huge gas envelopes.', 'Asteroids and comets are leftover building blocks that never quite became planets.', 'The giant-impact hypothesis says a Mars-sized body struck the young Earth, and the debris became the Moon.'], keyIdea: 'A spinning cloud flattened into a disk; wherever it was cold enough, ices fed the growth of giant worlds.', dive: 'We can watch the process today: ALMA’s radio images of young stars show protoplanetary disks with dark rings and gaps — the fingerprints of planets being carved out as they grow.', terms: [['solar nebula', 'The rotating cloud of gas and dust that collapsed into the Solar System 4.6 billion years ago.'], ['planetesimal', 'A kilometre-scale body built from sticking grains — the seed from which planets grew.'], ['protoplanetary disk', 'The flattened disk of gas and dust around a young star, imaged today by ALMA and JWST.']], activity: 'Stir flour into a shallow tray of water and watch clumps form and merge — grains sticking into bigger bodies is planet-building in miniature.', quick: { q: 'The frost line is the distance where…', options: ['Ices could survive and feed giant cores', 'The Sun became invisible', 'Asteroids could not form'], answer: 0, explain: 'Beyond the frost line, water and other ices stayed solid, letting growing cores capture huge gas envelopes.' }, fact: 'Apollo Moon rocks share Earth’s oxygen isotope fingerprint — support for the giant-impact story.' },
    { title: 'Smaller worlds and origins', body: 'Moons, asteroids, comets and icy Kuiper Belt objects are also part of the Solar System. A dwarf planet orbits the Sun and is nearly round, but has not cleared its orbital neighbourhood.', points: ['Pluto is in the Kuiper Belt; Ceres is in the asteroid belt.', 'Comets can develop a glowing coma and tail near the Sun.', 'Dust in the early solar nebula collided and gathered into larger bodies, including planets.'], keyIdea: 'Asteroids, comets and dwarf planets are the building blocks that never quite became planets.', dive: 'Ceres alone holds roughly a quarter of the entire asteroid belt’s mass. Far beyond it, the Oort Cloud — a vast shell of icy bodies — is the source of long-period comets that fall sunward once in a lifetime.', terms: [['dwarf planet', 'Orbits the Sun and is round under its own gravity, but has not cleared its orbital neighbourhood — Pluto’s 2006 category.'], ['Kuiper Belt', 'A ring of icy bodies beyond Neptune, home of Pluto and short-period comets.'], ['Oort Cloud', 'A distant spherical shell of icy bodies, the source of long-period comets.']], activity: 'Catch the Perseid meteors around 12 August: each streak is a grain of comet dust striking our atmosphere at about 59 km/s.', quick: { q: 'Why is Pluto classified as a dwarf planet?', options: ['It is too cold to have weather', 'It has not cleared its orbital neighbourhood', 'It has no moons'], answer: 1, explain: 'Pluto orbits among thousands of Kuiper Belt objects; a true planet must dominate its own orbital zone.' }, fact: 'Pluto was reclassified as a dwarf planet in 2006.' },
    { title: 'Moons, rings and tides', body: 'Hundreds of moons circle the planets, from cratered ice balls to worlds with weather. Tidal forces lock many moons to show one face forever, and on some worlds they knead the interior so hard it stays geologically alive.', points: ['Io is the most volcanically active world known; Europa hides a salty ocean beneath its icy crust.', 'Ganymede, larger than the planet Mercury, is the biggest moon in the Solar System.', 'Saturn’s dazzling rings are mostly water ice — countless chunks from dust grains to house-sized boulders.'], keyIdea: 'Tides lock moons to show one face and can keep small worlds geologically alive; rings are freshly-made debris.', dive: 'Saturn’s rings may be young and temporary: recent estimates put them at only 10–100 million years old, and they are being slowly eroded by radiation and falling “ring rain”. We may live in the middle of the rings’ short life.', terms: [['tidal locking', 'When tides slow a moon’s spin until one face always points at its planet — our Moon does it to itself.'], ['tidal heating', 'Flexing of a moon’s interior by its planet’s gravity, melting it from inside — Io’s volcanoes and Europa’s ocean.'], ['ring system', 'Countless chunks of orbiting ice and rock; Saturn’s are mostly water ice, from dust grains to house-sized boulders.']], activity: 'Watch the Moon’s craters near the terminator over a few nights: shadows lengthen and shift — the same tidal geometry that locks moons paints the phases.', quick: { q: 'Why does Io, a small moon, have hundreds of active volcanoes?', options: ['It is the closest moon to the Sun', 'Jupiter’s tides continually knead and heat its interior', 'It is cosmically very young'], answer: 1, explain: 'Io’s slightly stretched orbit means Jupiter’s tides flex it constantly, melting its interior — tidal heating at full power.' }, fact: 'Titan has rivers, lakes and rain — made of liquid methane instead of water.' },
    { title: 'Eclipses, seasons and phases', body: 'Seasons come from Earth’s 23.4° tilt, not from our changing distance to the Sun. The Moon’s phases are just its sunlit half turning toward us at different angles. Eclipses stay rare because the Moon’s orbit is tilted about 5° from Earth’s, so shadows line up only when the paths cross.', points: ['A solar eclipse needs a new Moon; a lunar eclipse needs a full Moon — and both need the orbital nodes lined up.', 'Earth’s sidereal day is 23 hours 56 minutes; the extra four minutes of our 24-hour day come from our motion around the Sun.', 'The same tides that raise the oceans push the Moon about 3.8 cm farther away every year.'], keyIdea: 'Tilt causes seasons, geometry causes phases, and eclipses only when Sun, Earth and Moon line up at the nodes.', dive: 'Eclipses arrive in “seasons” about twice a year — windows of a few weeks when the Sun sits near a node and alignments can happen. Astronomers who spotted the 18-year Saros rhythm could predict them without ever knowing an orbit.', terms: [['phase', 'The portion of the Moon’s sunlit half we see from Earth as the viewing angle changes through the month.'], ['node', 'One of two points where the Moon’s tilted path crosses Earth’s orbital plane — eclipse territory.'], ['umbra', 'The dark centre of a shadow; stand inside the Moon’s umbra and you see a total solar eclipse.']], activity: 'Recreate the phases with a ball and a lamp: hold the ball at arm’s length and walk it around your head — new, crescent, full, and back again.', quick: { q: 'A solar eclipse can only happen at…', options: ['Full Moon', 'New Moon, near a node', 'Any clear day'], answer: 1, explain: 'The Moon must sit between Earth and Sun (new Moon) and be crossing the orbital plane at a node for the shadows to line up.' }, fact: 'The Moon covers the Sun almost exactly during a total eclipse — a pure coincidence of size and distance.' }
  ], quiz: [
    { q: 'What actually causes Earth’s seasons?', options: ['The tilted axis', 'Changing distance to the Sun', 'The Moon’s pull'], answer: 0, explain: 'Earth’s 23.4° tilt changes how directly sunlight strikes each hemisphere through the year.' },
    { q: 'Which moon has rivers, lakes and rain of liquid methane?', options: ['Europa', 'Titan', 'Io'], answer: 1, explain: 'Titan’s thick atmosphere cycles methane much like Earth cycles water.' },
    { q: 'Roughly where was the Solar System’s frost line?', options: ['Inside Mercury’s orbit', 'Between Earth and Venus', 'Near Jupiter’s orbit'], answer: 2, explain: 'Beyond the frost line ices could survive, letting the giant planets grow enormous.' }
  ] },
  { title: 'Stars & Stellar Evolution', subtitle: 'How stars are born and change', image: 'visual-nebula.png', accent: 'ember', intro: 'Stars are hot balls of gas, mainly hydrogen and helium. They shine because nuclear fusion releases energy in their cores, and their birth mass shapes how they eventually change.', topics: [
    { title: 'From nebula to main sequence', body: 'Gravity pulls gas and dust in a nebula together. The cloud shrinks and heats; when the core becomes hot and dense enough, hydrogen fusion begins. The star enters its long, stable main-sequence stage.', points: ['Fusion changes hydrogen into helium and releases energy.', 'Outward energy balances gravity pulling inward.', 'The Sun is currently a main-sequence star.'], keyIdea: 'Gravity gathers the cloud and pressure ignites the core: fusion marks the start of a star’s stable life.', dive: 'JWST now watches this happen: inside the “Pillars of Creation” of the Eagle Nebula, infrared eyes see protostars firing jets into their shrouds — the opening minutes of stellar lives, some 6,000 light-years away.', terms: [['nebula', 'A cloud of interstellar gas and dust — the raw material and often the cradle of stars.'], ['protostar', 'A collapsing cloud fragment still warming by contraction, before fusion switches on.'], ['main sequence', 'The long, stable hydrogen-burning stage; the Sun has about five billion years of it left.']], activity: 'On a winter night find the fuzzy middle “star” of Orion’s sword below the belt — that is the Orion Nebula, stars being born before your eyes.', quick: { q: 'A protostar officially becomes a star when…', options: ['It starts to spin', 'Hydrogen fusion ignites in its core', 'Its nebula fully disappears'], answer: 1, explain: 'Once the core is hot and dense enough for hydrogen fusion, outward energy balances gravity and the star joins the main sequence.' }, fact: 'The Orion Nebula is a region where new stars are forming.' },
    { title: 'Reading a star’s light', body: 'Starlight carries fingerprints. Dark lines in a star’s spectrum reveal which elements its atmosphere holds, and the overall colour sorts stars into temperature classes from hot O stars down to cool M dwarfs. Plotted on the Hertzsprung–Russell diagram, these properties sketch the stages of stellar life.', points: ['Spectral classes run O, B, A, F, G, K, M from hottest to coolest; the Sun is a G2 star.', 'Main-sequence stars fuse hydrogen; giants and white dwarfs occupy other regions of the H–R diagram.', '1868 — helium was spotted in the Sun’s spectrum before anyone found it on Earth.'], keyIdea: 'Spectral lines name a star’s elements; the H–R diagram turns colour and brightness into life stages.', dive: 'In 1925 Cecilia Payne showed that stars are overwhelmingly hydrogen and helium — a result so strange for its day that reviewers made her soften it. Within a few years it was confirmed; her thesis is now often called the most brilliant ever written in astronomy.', terms: [['spectrum', 'Light spread into its colours; dark absorption lines spell out which elements the gas contains.'], ['absorption line', 'A dark line where atoms in a star’s atmosphere swallow specific wavelengths of light.'], ['H–R diagram', 'The chart of stellar temperature against brightness, sketching the stages of stellar life.']], activity: 'Reflect sunlight off an old CD onto paper: the little rainbow carries dark solar absorption lines — a spectroscope from a kitchen drawer.', quick: { q: 'On the H–R diagram, the main sequence runs…', options: ['From hot, bright stars down to cool, dim ones', 'From all red stars to all blue ones', 'Randomly, with no pattern'], answer: 0, explain: 'O and B stars sit hot and luminous at one end; cool red dwarfs gather dimly at the other, with the Sun in between.' }, fact: 'The name helium comes from Helios, the Greek god of the Sun.' },
    { title: 'Fusing heavier elements', body: 'A star is a fusion furnace, building heavier nuclei step by step. Sun-like stars stop at helium and carbon. Massive stars push on through carbon, oxygen and silicon until their cores turn to iron — an element that yields no energy when fused. The balance fails, the core collapses in seconds, and the star explodes.', points: ['Up to iron, fusion releases energy; fusing iron costs energy, so an iron core is a dead end.', 'The blast forges and scatters new elements — the calcium in bones and the iron in blood came from such explosions.', 'Many of the heaviest elements, including much of Earth’s gold, are thought to be forged when neutron stars collide.'], keyIdea: 'Stars build the elements up to iron; anything heavier needs a stellar explosion or a neutron-star collision.', dive: 'Physics caught the furnaces in action: neutrinos from supernova 1987A confirmed the collapsing-core picture, and in 2017 gravitational waves from colliding neutron stars lit up a kilonova — freshly minted gold, observed at last.', terms: [['nucleosynthesis', 'The forging of atomic nuclei — inside stars, in supernovae, and in neutron-star collisions.'], ['supernova', 'The explosive death of a massive star, briefly outshining its whole galaxy.'], ['kilonova', 'The flash of heavy-element creation when two neutron stars merge, first observed in 2017.']], activity: 'Read your own hand as a star’s legacy: the iron in your blood, the calcium in your bones and the oxygen in every breath were all forged in stars.', quick: { q: 'Why does an iron core spell the end for a massive star?', options: ['Iron is too magnetic to fuse', 'Fusing iron consumes energy instead of releasing it', 'Iron evaporates at stellar temperatures'], answer: 1, explain: 'Up to iron, fusion pays energy out; iron costs energy in. The core can no longer hold itself up and collapses in seconds.' }, fact: 'You are made of atoms assembled inside stars that died before the Sun was born.' },
    { title: 'White dwarfs, pulsars and black holes', body: 'What survives an ending depends on the mass left behind. Below about 1.4 solar masses, quantum pressure halts the collapse and a white dwarf forms. Heavier cores crush into city-sized neutron stars; past roughly three solar masses, nothing can stop the fall and a black hole appears.', points: ['A sugar-cube-sized piece of neutron star would weigh about a billion tonnes on Earth.', '1967 — Jocelyn Bell Burnell detected the first pulsar: a spinning neutron star sweeping radio beams like a lighthouse.', 'White-dwarf supernovae burn with near-identical brightness, letting astronomers measure cosmic distances — and discover dark energy in 1998.'], keyIdea: 'Leftover mass chooses the corpse: white dwarf below 1.4 Suns, neutron star beyond, black hole past about three.', dive: 'The evidence moved from indirect hints to direct signal: LIGO’s 2015 detection of gravitational waves from two merging black holes confirmed the prediction, decades after Cygnus X-1 first hinted at a hungry horizon.', terms: [['white dwarf', 'The Earth-sized ember of a Sun-like star, held up by quantum pressure — no fusion left.'], ['neutron star', 'A city-sized core crushed to nuclear density; a sugar cube of it would weigh about a billion tonnes.'], ['event horizon', 'The boundary of no return around a black hole, where escape would require exceeding the speed of light.']], activity: 'Put Sirius on your list: its faint white-dwarf companion Sirius B is a genuine small-telescope challenge when the pair is at its widest.', quick: { q: 'What is the event horizon of a black hole?', options: ['A solid surface of collapsed matter', 'The boundary beyond which light cannot escape', 'A ring of orbiting debris'], answer: 1, explain: 'Inside the event horizon, escape would need faster-than-light speed — so nothing, light included, gets out.' }, fact: 'The first pulsar’s steady radio beats were nicknamed LGM-1 — “little green men”.' },
    { title: 'Different stars, different endings', body: 'When core hydrogen runs low, a star changes. Lower-mass stars swell into red giants and leave white dwarfs. Massive stars can explode as supernovae and leave neutron stars or black holes.', points: ['A supernova spreads heavy elements into space.', 'A neutron star can be only about 20–25 km wide yet more massive than the Sun.', 'A black hole has an event horizon beyond which light cannot escape.'], keyIdea: 'Birth mass decides the death: red giants fade to white dwarfs, while massive stars explode.', dive: 'The Sun’s file is already written: in about five billion years it swells into a red giant, drifts off its outer layers as a planetary nebula, and ends as a white dwarf. Betelgeuse, far heavier, is expected to go supernova within the next hundred thousand years.', terms: [['red giant', 'A swollen, cooled late-stage star; the Sun will engulf Mercury and Venus in this phase.'], ['planetary nebula', 'The glowing shed shell of a dying Sun-like star — a misnomer from 18th-century telescopes.'], ['supernova remnant', 'The expanding wreckage and enriched gas left behind by a stellar explosion, like the Crab Nebula.']], activity: 'Betelgeuse surprised astronomers by dimming dramatically in 2019–20 — follow astronomy news; when it finally explodes it will be visible in daylight.', quick: { q: 'Our Sun will end its life as…', options: ['A neutron star', 'A white dwarf', 'A black hole'], answer: 1, explain: 'The Sun is far below the supernova threshold: it will swell to a red giant, shed a planetary nebula and cool as a white dwarf.' } }
  ], quiz: [
    { q: 'What balances gravity in a stable main-sequence star?', options: ['Pressure from fusion energy', 'The star’s magnetic field', 'Centrifugal force from its spin'], answer: 0, explain: 'Outward pressure from energy released by fusion holds the star up against gravity.' },
    { q: 'Fusion in a massive star’s core stops for good once the core is mostly…', options: ['Helium', 'Carbon', 'Iron'], answer: 2, explain: 'Fusing iron consumes energy instead of releasing it, so the core collapses and the star explodes.' },
    { q: 'What did Jocelyn Bell Burnell discover in 1967?', options: ['Pulsars', 'Quasars', 'Cepheid variables'], answer: 0, explain: 'She detected the first pulsar — a spinning neutron star beaming radio waves.' }
  ] },
  { title: 'Galaxies & Cosmology', subtitle: 'The universe at its largest scales', image: 'visual-galaxy.png', accent: 'violet', intro: 'Galaxies are collections of stars, gas, dust and dark matter held together by gravity. Cosmology studies the universe’s origin, structure, evolution and future.', topics: [
    { title: 'Galaxies and the cosmic web', body: 'The Milky Way is a barred spiral. Its disk contains most of its stars, gas and dust; our Solar System lies in the Orion Arm. Across the universe, galaxies gather into filaments and clusters separated by voids.', points: ['Spiral galaxies have disks and arms; elliptical galaxies are round or oval; irregular galaxies have no clear shape.', 'The Milky Way and Andromeda are in the Local Group.', 'The observable universe is about 93 billion light-years across.'], keyIdea: 'Gravity strings hundreds of billions of galaxies into filaments and walls around empty voids.', dive: 'Our address climbs in steps: Earth in the Solar System, in the Orion Arm of the Milky Way, in the Local Group of roughly 80 galaxies, in the Laniakea supercluster of some 100,000 — each level held in gravity’s web.', terms: [['spiral galaxy', 'A flat disk of stars with winding arms; the Milky Way is a barred spiral.'], ['elliptical galaxy', 'A rounded ball of older stars, often built from merged spirals.'], ['Local Group', 'Our cluster of roughly 80 galaxies, dominated by the Milky Way and Andromeda.']], activity: 'On a dark autumn evening find the Andromeda Galaxy by eye — 2.5 million light-years away, the farthest thing visible without a telescope.', quick: { q: 'The Milky Way is classified as a…', options: ['Barred spiral galaxy', 'Giant elliptical galaxy', 'Irregular galaxy'], answer: 0, explain: 'Our galaxy is a barred spiral: a central bar of stars with winding arms, one of which hosts the Sun.' } },
    { title: 'Island universes', body: 'In 1920 astronomers still argued whether the spiral nebulae were clouds inside the Milky Way or separate “island universes”. Edwin Hubble settled the Great Debate by finding Cepheid variable stars in Andromeda and measuring their distance — far beyond our galaxy. Then distant galaxies turned out to slide toward the red end of the spectrum.', points: ['Cepheids pulse with a period tied to their true brightness — a ready-made cosmic measuring tape.', '1929 — Hubble and Milton Humason showed that a galaxy’s redshift grows with its distance: space itself is expanding.', 'Vesto Slipher’s earlier spectra had already caught the nebulae racing away at enormous speeds.'], keyIdea: 'Cepheid yardsticks settled the Great Debate — and redshifts revealed that space itself expands.', dive: 'Hubble’s ruler was built by Henrietta Swan Leavitt, who discovered that a Cepheid’s pulsation period reveals its true brightness. Standard candles like these still anchor every distance measurement in cosmology.', terms: [['Cepheid variable', 'A pulsing star whose period betrays its true brightness — a ready-made cosmic measuring tape.'], ['standard candle', 'An object of known true brightness whose apparent dimness reveals its distance.'], ['redshift', 'The stretching of light to longer wavelengths as space expands or a source recedes.']], activity: 'Draw dots on a rubber-band grid and stretch it: every dot sees its neighbours recede, and no dot is the centre — Hubble’s law in one tug.', quick: { q: 'A galaxy’s redshift grows with its…', options: ['Mass', 'Distance', 'Spin'], answer: 1, explain: 'Hubble’s 1929 law: the farther the galaxy, the more space has stretched its light on the way to us.' }, fact: 'Andromeda’s light is blueshifted — it is actually approaching, and the two galaxies will merge in roughly 4.5 billion years.' },
    { title: 'Quasars and monster black holes', body: 'Some galaxy centres outshine the galaxies around them. These quasars are supermassive black holes swallowing gas, which heats to brilliant temperatures on the way in. Our own galaxy hosts a quiet one — Sagittarius A*, about four million times the Sun’s mass.', points: ['1963 — Maarten Schmidt identified the enormous redshift of quasar 3C 273, placing it billions of light-years away.', '2019 — the Event Horizon Telescope released the first image of a black hole’s shadow, in the galaxy M87.', '2022 — the same Earth-sized network of telescopes imaged Sagittarius A*, our galaxy’s own black hole.'], keyIdea: 'Feeding supermassive black holes can outshine their whole galaxy — and every big galaxy owns one.', dive: 'Because quasars blaze across billions of light-years, astronomers use them as background lamps: gas clouds between here and there stamp fingerprints into the beam, letting us census the thin matter between the galaxies.', terms: [['quasar', 'The brilliant core of a galaxy where a supermassive black hole is devouring gas at full rate.'], ['accretion disk', 'The swirling disk of infalling gas, heated to brilliance by friction before crossing the horizon.'], ['Sagittarius A*', 'The Milky Way’s own quiet black hole, about four million solar masses, imaged in 2022.']], activity: 'Look up the Event Horizon Telescope’s image of M87: the glowing ring is gravity-bent light from gas orbiting a 6.5-billion-solar-mass shadow.', quick: { q: 'A quasar’s enormous energy comes from…', options: ['Nuclear fusion among its stars', 'Gas heating as it spirals into a black hole', 'Repeated supernova explosions'], answer: 1, explain: 'Infalling gas compresses and heats to extreme temperatures in the accretion disk — a fraction of the fuel outshines the entire galaxy.' }, fact: 'The EHT links radio dishes from Hawaii to the South Pole into a lens nearly as wide as Earth.' },
    { title: 'Cosmic dawn', body: 'The universe became transparent about 380,000 years after the Big Bang, releasing the cosmic microwave background we still detect today. After a long dark age the first stars ignited, and their ultraviolet light re-ionized the gas between galaxies. The James Webb telescope is now finding galaxies that existed only a few hundred million years after the beginning.', points: ['The CMB is the oldest light we can observe — a snapshot of the universe as an infant.', 'The very first stars were massive, metal-free giants; none has yet been seen directly.', 'JWST’s gold-coated mirror reflects infrared light — the stretched light of the earliest galaxies.'], keyIdea: 'The CMB is the infant universe’s afterglow; the first massive stars ended the cosmic dark ages.', dive: 'Webb keeps breaking its own records: in 2024 it confirmed JADES-GS-z14-0, a galaxy seen just 290 million years after the Big Bang — its ultraviolet light stretched by expansion into the infrared Webb was built to catch.', terms: [['cosmic microwave background', 'The oldest observable light, released when the universe turned transparent 380,000 years after the Big Bang.'], ['cosmic dark age', 'The era after the CMB and before the first stars, when no lights shone anywhere.'], ['reionization', 'The era when early stars’ ultraviolet light re-energised the gas between the galaxies.']], activity: 'Analogue television snow included roughly one per cent CMB light — the Big Bang’s afterglow hissing in every living room before the digital switch.', quick: { q: 'The cosmic microwave background is…', options: ['Light from the very first stars', 'Leftover glow from when the universe became transparent', 'Static from nearby radio galaxies'], answer: 1, explain: 'At 380,000 years old the universe cooled enough for light to travel freely; that first light, stretched about a thousand-fold, is the CMB.' }, fact: 'Webb has confirmed galaxies shining when the universe was under 400 million years old.' },
    { title: 'Expansion and the unseen universe', body: 'The Big Bang model describes an early hot, dense universe about 13.8 billion years ago; space itself has expanded since. Redshift in distant galaxies is evidence of expansion.', points: ['The cosmic microwave background is ancient light from when the universe became transparent.', 'Dark matter is inferred from its gravitational effects and helps hold structures together.', 'Dark energy is the name for what drives the universe’s accelerated expansion; its nature remains unknown.'], keyIdea: 'Ordinary matter is only about 5% of the universe; dark matter and dark energy make up the rest.', dive: 'The 1998 discovery that expansion is speeding up earned the 2011 Nobel Prize. Planck’s map of the CMB now assigns the cosmos: roughly 68% dark energy, 27% dark matter and just 5% everything we have ever seen.', terms: [['dark matter', 'Unseen mass revealed only by gravity — it binds galaxies and clusters, outweighing normal matter about five to one.'], ['dark energy', 'Whatever drives the accelerating expansion; discovered via distant supernovae in 1998, still unexplained.'], ['type Ia supernova', 'A white-dwarf explosion of near-standard brightness — the yardstick that measured cosmic acceleration.']], activity: 'Sketch a spiral galaxy’s rotation curve: outer stars should slow with distance, but real ones hold speed — the gap in your drawing is dark matter’s fingerprint.', quick: { q: 'Dark energy is the name for…', options: ['A kind of invisible star', 'Whatever drives the universe’s accelerating expansion', 'The same thing as dark matter'], answer: 1, explain: 'Two effects, two names: dark matter pulls structures together; dark energy pushes space apart, faster and faster.' } }
  ], quiz: [
    { q: 'How did Hubble prove Andromeda lies beyond the Milky Way?', options: ['By timing Cepheid variable stars in it', 'By measuring its colour', 'By counting its stars one by one'], answer: 0, explain: 'Cepheids gave Andromeda’s distance — far outside our galaxy.' },
    { q: 'The redshift of distant galaxies tells us that…', options: ['Galaxies are cooling', 'Space itself is expanding', 'The Milky Way is shrinking'], answer: 1, explain: 'The greater a galaxy’s distance, the greater its redshift — the signature of cosmic expansion.' },
    { q: 'When was the first image of a black hole’s shadow released?', options: ['1990', '2009', '2019'], answer: 2, explain: 'The Event Horizon Telescope imaged M87’s black hole in 2019, and Sagittarius A* in 2022.' }
  ] },
  { title: 'Space Exploration & Missions', subtitle: 'How we explore beyond Earth', image: 'visual-rover.png', accent: 'sage', intro: 'Space exploration uses telescopes, satellites, spacecraft, robots and human missions to study planets, stars, galaxies and the possibility of life beyond Earth.', topics: [
    { title: 'Rovers, orbiters and probes', body: 'Robotic spacecraft can explore places that are difficult or dangerous for people to reach. Each kind of craft has a different job.', points: ['A rover moves across a planetary surface; Perseverance explores Mars.', 'An orbiter circles a planet and can map its surface or study its atmosphere.', 'A probe investigates space, flying past an object or entering an atmosphere.'], keyIdea: 'Each craft answers a different question: flybys for range, orbiters for maps, landers and rovers for ground truth.', dive: 'The Voyagers owe their grand tour to geometry: a planetary alignment that recurs every 176 years let two spacecraft hop from Jupiter to Saturn to Uranus to Neptune on almost no fuel — each planet’s gravity handing them to the next.', terms: [['flyby', 'A fast pass by a target, trading depth for range — how four planets were surveyed in one mission.'], ['orbiter', 'A craft that circles its world, mapping surface and atmosphere over months and years.'], ['rover', 'A mobile laboratory that crosses a surface, like Perseverance in Jezero Crater.']], activity: 'Try NASA’s free “Eyes on the Solar System”: ride along with real spacecraft positions, updated live, from Voyager 1 to Perseverance.', quick: { q: 'Why do missions usually send an orbiter before a rover?', options: ['Orbiters are cheaper to fuel', 'Orbiter maps pick safe, interesting landing sites', 'Rovers cannot reach other planets'], answer: 1, explain: 'High-resolution orbital maps choose the landing site and keep rover drivers oriented — ground truth works best with a view from above.' } },
    { title: 'Rockets and the road to orbit', body: 'Reaching space is a fight against gravity, won with speed — about 7.8 kilometres per second for low orbit. Most of a rocket is fuel and tanks, with the payload riding a carefully controlled explosion. Once in orbit a spacecraft simply keeps falling around Earth; no engine is needed to stay up.', points: ['1957 — Sputnik 1 became the first artificial satellite; 1961 — Yuri Gagarin became the first human in orbit.', 'The Saturn V that sent Apollo moonward stood about 111 metres tall — taller than the Statue of Liberty.', 'Reusable boosters, like Falcon 9’s landing first stages, have cut the cost of reaching orbit.'], keyIdea: 'Orbit is a speed, not a height: reach about 7.8 km/s sideways and you fall around Earth forever.', dive: 'The rocket equation is unforgiving: every extra metre per second costs fuel that itself must be lifted. That is why rockets drop stages as they climb — shedding empty tanks is often cheaper than carrying them.', terms: [['orbital velocity', 'The horizontal speed needed to keep falling around a body; about 7.8 km/s for low Earth orbit.'], ['staging', 'Dropping spent engines and empty tanks mid-flight so the remaining vehicle is lighter.'], ['escape velocity', 'The speed needed to leave a body entirely: 11.2 km/s from Earth, versus the Moon’s 2.4 km/s.']], activity: 'Build a water-bottle rocket: pushing water down pushes the bottle up — Newton’s third law at playground scale.', quick: { q: 'What mainly keeps a spacecraft in low Earth orbit?', options: ['Flying above the atmosphere', 'About 7.8 km/s of horizontal speed', 'Constant small engine burns'], answer: 1, explain: 'Orbit is perpetual falling with enough sideways speed to keep missing the ground — altitude alone is not enough.' }, fact: 'Roughly nine of every ten tonnes on a launch pad is propellant, burned away within minutes.' },
    { title: 'Missions that changed our view', body: 'Apollo 11 first landed people on the Moon in 1969. Voyager 1 and 2 visited the outer planets and later entered interstellar space. Hubble and Webb observe the cosmos from space.', points: ['The ISS is a crewed research laboratory in low Earth orbit.', 'Curiosity studies Gale Crater; Perseverance explores Jezero Crater and collects rock cores.', 'Ingenuity demonstrated powered, controlled flight on another planet.'], keyIdea: 'From Apollo to Webb, each flagship mission rewrote a chapter of what we know — and what we ask next.', dive: 'Voyager 1 is now more than 24 billion kilometres out, in interstellar space since 2012. Its radio signal, travelling at light speed, still takes over 22 hours to reach home — the slowest conversation humanity has ever held.', terms: [['interstellar space', 'Beyond the Sun’s heliosphere, where a craft swims in the galaxy’s own thin gas.'], ['gravitational assist', 'Borrowing a planet’s orbital motion to speed or steer a spacecraft — free push, used by the Voyagers.'], ['sample return', 'Bringing material home for laboratory study, from Apollo’s Moon rocks to Perseverance’s sealed tubes.']], activity: 'Listen online to the Golden Record’s greetings in 55 languages — the mixed message humanity attached to Voyager’s hull.', quick: { q: 'Voyager 1 made history again in 2012 when it…', options: ['Flew past Neptune', 'Entered interstellar space', 'Landed on Titan'], answer: 1, explain: 'In 2012 Voyager 1 crossed the heliopause: the Sun’s wind gave way to interstellar gas, and the craft left the Sun’s bubble.' }, fact: 'Ingenuity flew 72 times on Mars alongside Perseverance.' },
    { title: 'Living and working in orbit', body: 'On the International Space Station astronauts watch 16 sunrises a day while their bodies quietly change. Muscles and bones weaken without gravity’s load, so crews exercise about two hours daily. Water and air are recycled, because every kilogram launched costs a small fortune.', points: ['The ISS recycles almost all of its water — even humidity from breath and sweat — into drinkable supplies.', 'Without exercise, bone density can fall several times faster than in elderly people on Earth.', 'Radiation is the biggest health challenge for future Mars missions, which may last two to three years.'], keyIdea: 'Microgravity reshapes bodies and budgets: crews exercise hard and recycle nearly everything.', dive: 'Without countermeasures astronauts can lose roughly one per cent of bone density each month. Two hours of daily exercise — treadmills, cycles and resistance machines — keeps crews strong enough to walk after landing.', terms: [['microgravity', 'The free-fall condition of orbit: weightlessness, not zero gravity — Earth’s pull up there is still about 90% as strong.'], ['low Earth orbit', 'The 300–500 km band where the ISS circles Earth every ~90 minutes at 27,600 km/h.'], ['regenerative life support', 'Recycling air and water aboard — the ISS recovers humidity, sweat and even urine into drinking water.']], activity: 'Track the ISS with a spotting app: it is one of the brightest objects in the sky and crosses your horizon in about ten minutes.', quick: { q: 'Astronauts on the ISS exercise about two hours daily mainly to…', options: ['Slow muscle and bone loss in weightlessness', 'Pass the time between experiments', 'Generate power for the station'], answer: 0, explain: 'In microgravity, muscles and bones unload; daily resistance and cardio training keeps crews healthy for return to Earth.' }, fact: 'From the ISS cupola, astronauts photograph hurricanes, auroras and volcanic plumes for scientists back home.' }
  ], quiz: [
    { q: 'Which craft made the first powered, controlled flight on another planet?', options: ['Curiosity', 'Ingenuity', 'Voyager 2'], answer: 1, explain: 'NASA’s Ingenuity helicopter flew 72 times on Mars alongside the Perseverance rover.' },
    { q: 'What did Voyager 1 photograph from beyond Neptune in 1990?', options: ['A comet striking Jupiter', 'Earth as a “Pale Blue Dot”', 'Saturn’s polar hexagon'], answer: 1, explain: 'At Carl Sagan’s request, Voyager 1 turned back to photograph Earth — a “pale blue dot”.' },
    { q: 'About how many sunrises does an ISS astronaut see in one day?', options: ['16', '2', '1'], answer: 0, explain: 'The ISS orbits Earth roughly every 90 minutes, so crews see about 16 sunrises a day.' }
  ] }
];
